    def test_bootstrap(self, cli_venv, venv_path):
        site_package_path = self._site_packages_dir(venv_path)

        prior_site_dir = set(os.listdir(site_package_path))
        cli_venv.bootstrap(
            ArtifactType.SYSTEM_SANDBOX.value, download_deps=False
