def _handle_paused_run(self, run_response: RunResponse) -> Any:
    from rich.text import Text

    tool_calls_content = Text("Run is paused. ")
    if run_response.tools is not None:
        if any(tc.requires_confirmation for tc in run_response.tools):
            tool_calls_content.append("The following tool calls require confirmation:\n")
        for tool_call in run_response.tools:
            if tool_call.requires_confirmation:
                args_str = ""
                for arg, value in tool_call.tool_args.items() if tool_call.tool_args else {}:
                    args_str += f"{arg}={value}, "
                args_str = args_str.rstrip(", ")
                tool_calls_content.append(f"• {tool_call.tool_name}({args_str})\n")
        if any(tc.requires_user_input for tc in run_response.tools):
            tool_calls_content.append("The following tool calls require user input:\n")
        for tool_call in run_response.tools:
            if tool_call.requires_user_input:
                args_str = ""
                for arg, value in tool_call.tool_args.items() if tool_call.tool_args else {}:
                    args_str += f"{arg}={value}, "
                args_str = args_str.rstrip(", ")
                tool_calls_content.append(f"• {tool_call.tool_name}({args_str})\n")
        if any(tc.external_execution_required for tc in run_response.tools):
            tool_calls_content.append("The following tool calls require external execution:\n")
        for tool_call in run_response.tools:
            if tool_call.external_execution_required:
                args_str = ""
                for arg, value in tool_call.tool_args.items() if tool_call.tool_args else {}:
                    args_str += f"{arg}={value}, "
                args_str = args_str.rstrip(", ")
                tool_calls_content.append(f"• {tool_call.tool_name}({args_str})\n")

    # Create panel for response
    response_panel = create_panel(
        content=tool_calls_content,
        title="Run Paused",
        border_style="blue",
    )
    return response_panel

def load(
    self,
    recreate: bool = False,
    upsert: bool = True,
    skip_existing: bool = True,
    filters: Optional[Dict[str, Any]] = None,
) -> None:
    """Load the website contents to the vector db"""

    if self.vector_db is None:
        logger.warning("No vector db provided")
        return

    if self.reader is None:
        logger.warning("No reader provided")
        return

    if recreate:
        log_debug("Dropping collection")
        self.vector_db.drop()

    log_debug("Creating collection")
    self.vector_db.create()

    log_info("Loading knowledge base")

    # Given that the crawler needs to parse the URL before existence can be checked
    # We check if the website url exists in the vector db if recreate is False
    urls_to_read = self.urls.copy()
    if not recreate:
        for url in urls_to_read:
            log_debug(f"Checking if {url} exists in the vector db")
            if self.vector_db.name_exists(name=url):
                log_debug(f"Skipping {url} as it exists in the vector db")
                urls_to_read.remove(url)

    num_documents = 0
    for url in urls_to_read:
        if document_list := self.reader.read(url=url):
            # Filter out documents which already exist in the vector db
            if not recreate:
                document_list = [document for document in document_list if not self.vector_db.doc_exists(document)]
                if not document_list:
                    continue
            if upsert and self.vector_db.upsert_available():
                self.vector_db.upsert(documents=document_list, filters=filters)
            else:
                self.vector_db.insert(documents=document_list, filters=filters)
            num_documents += len(document_list)
            log_info(f"Loaded {num_documents} documents to knowledge base")

    if self.optimize_on is not None and num_documents > self.optimize_on:
        log_debug("Optimizing Vector DB")
        self.vector_db.optimize()

def prune_actor_input_schema(input_schema: Dict[str, Any]) -> Tuple[Dict[str, Any], List[str]]:
    """Get the input schema from the Actor build and trim descriptions.

    Args:
        input_schema (Dict[str, Any]): The input schema from the Actor build

    Returns:
        Tuple[Dict[str, Any], List[str]]: A tuple containing the pruned properties and required fields
    """
    properties = input_schema.get("properties", {})
    required = input_schema.get("required", [])

    properties_out: Dict[str, Any] = {}
    for item, meta in properties.items():
        properties_out[item] = {}
        if desc := meta.get("description"):
            properties_out[item]["description"] = (
                desc[:MAX_DESCRIPTION_LEN] + "..." if len(desc) > MAX_DESCRIPTION_LEN else desc
            )
        for key_name in ("type", "default", "prefill", "enum"):
            if value := meta.get(key_name):
                properties_out[item][key_name] = value

    return properties_out, required

def get_recent_sessions(
    self,
    user_id: Optional[str] = None,
    entity_id: Optional[str] = None,
    limit: Optional[int] = 2,
) -> List[Session]:
    """Get the last N sessions, ordered by created_at descending.

    Args:
        num_history_sessions: Number of most recent sessions to return
        user_id: Filter by user ID
        entity_id: Filter by entity ID (agent_id, team_id, or workflow_id)

    Returns:
        List[Session]: List of most recent sessions
    """
    sessions: List[Session] = []
    try:
        with self.SqlSession.begin() as sess:
            # Build base query
            stmt = select(self.table)

            # Add filters
            if user_id is not None:
                stmt = stmt.where(self.table.c.user_id == user_id)
            if entity_id is not None:
                if self.mode == "agent":
                    stmt = stmt.where(self.table.c.agent_id == entity_id)
                elif self.mode == "team":
                    stmt = stmt.where(self.table.c.team_id == entity_id)
                elif self.mode == "workflow":
                    stmt = stmt.where(self.table.c.workflow_id == entity_id)

            # Order by created_at desc and limit results
            stmt = stmt.order_by(self.table.c.created_at.desc())
            if limit is not None:
                stmt = stmt.limit(limit)

            # Execute query
            rows = sess.execute(stmt).fetchall()
            for row in rows:
                if row.session_id is not None:
                    if self.mode == "agent":
                        session = AgentSession.from_dict(row._mapping)  # type: ignore
                        if session is not None:
                            sessions.append(session)
                    elif self.mode == "team":
                        session = TeamSession.from_dict(row._mapping)  # type: ignore
                        if session is not None:
                            sessions.append(session)
                    elif self.mode == "workflow":
                        session = WorkflowSession.from_dict(row._mapping)  # type: ignore
                        if session is not None:
                            sessions.append(session)

    except Exception as e:
        if "doesn't exist" in str(e):
            log_debug(f"Table does not exist: {self.table.name}")
            self.create()
        else:
            logger.error(f"Error getting last {num_history_sessions} sessions: {e}")

    return sessions

