def checkAndReloadIfNeeded(self):
    now = int(time.time() * 1000)
    if now - self.memory_cache["last_check"] < CACHE_CHECK_INTERVAL_MS:
        return
    self.memory_cache["last_check"] = now

    try:
        file_path = self.getCredentialFilePath()
        stat = file_path.stat()
        file_mod_time = int(stat.st_mtime * 1000)
        if file_mod_time > self.memory_cache["file_mod_time"]:
            await self.reloadCredentialsFromFile()
            self.memory_cache["file_mod_time"] = file_mod_time
    except FileNotFoundError:
        self.memory_cache["file_mod_time"] = 0
    except Exception as e:
        self.memory_cache["credentials"] = None
        raise TokenManagerError(TokenError.FILE_ACCESS_ERROR, str(e), e)

async def getValidCredentials(self, qwen_client: IQwenOAuth2Client, force_refresh: bool = False):
    try:
        self.checkAndReloadIfNeeded()

        if (
            self.memory_cache["credentials"]
            and not force_refresh
            and self.isTokenValid(self.memory_cache["credentials"])
        ):
            return self.memory_cache["credentials"]

        if self.refresh_promise:
            return await self.refresh_promise

        self.refresh_promise = asyncio.create_task(self.performTokenRefresh(qwen_client, force_refresh))
        credentials = await self.refresh_promise
        self.refresh_promise = None
        return credentials
    except Exception as e:
        if isinstance(e, TokenManagerError):
            raise
        raise TokenManagerError(TokenError.REFRESH_FAILED, str(e), e)

async def acquireLock(self, lock_path: Path):
    max_attempts = 50
    attempt_interval = 200  # ms
    lock_id = str(uuid.uuid4())

    for _ in range(max_attempts):
        try:
            with open(lock_path, "w") as f:
                f.write(lock_id)
            return
        except:
            try:
                stat = os.stat(str(lock_path))
                lock_age = int(time.time() * 1000) - int(stat.st_mtime * 1000)
                if lock_age > LOCK_TIMEOUT_MS:
                    try:
                        await os.unlink(str(lock_path))
                    except:
                        pass
            except:
                pass
            await asyncio.sleep(attempt_interval / 1000)
    raise TokenManagerError(TokenError.LOCK_TIMEOUT, "Failed to acquire lock")

async def releaseLock(self, lock_path: Path):
    try:
        await os.unlink(str(lock_path))
    except:
        pass

def load(self) -> Image.core.PixelAccess | None:
    """Load image data based on tile list"""

    if not self.tile and self._im is None:
        msg = "cannot load this image"
        raise OSError(msg)

    pixel = Image.Image.load(self)
    if not self.tile:
        return pixel

    self.map: mmap.mmap | None = None
    use_mmap = self.filename and len(self.tile) == 1

    readonly = 0

    # look for read/seek overrides
    if hasattr(self, "load_read"):
        read = self.load_read
        # don't use mmap if there are custom read/seek functions
        use_mmap = False
    else:
        read = self.fp.read

    if hasattr(self, "load_seek"):
        seek = self.load_seek
        use_mmap = False
    else:
        seek = self.fp.seek

    if use_mmap:
        # try memory mapping
        decoder_name, extents, offset, args = self.tile[0]
        if isinstance(args, str):
            args = (args, 0, 1)
        if (
            decoder_name == "raw"
            and isinstance(args, tuple)
            and len(args) >= 3
            and args[0] == self.mode
            and args[0] in Image._MAPMODES
        ):
            if offset < 0:
                msg = "Tile offset cannot be negative"
                raise ValueError(msg)
            try:
                # use mmap, if possible
                import mmap

                with open(self.filename) as fp:
                    self.map = mmap.mmap(fp.fileno(), 0, access=mmap.ACCESS_READ)
                if offset + self.size[1] * args[1] > self.map.size():
                    msg = "buffer is not large enough"
                    raise OSError(msg)
                self.im = Image.core.map_buffer(
                    self.map, self.size, decoder_name, offset, args
                )
                readonly = 1
                # After trashing self.im,
                # we might need to reload the palette data.
                if self.palette:
                    self.palette.dirty = 1
            except (AttributeError, OSError, ImportError):
                self.map = None

    self.load_prepare()
    err_code = -3  # initialize to unknown error
    if not self.map:
        # sort tiles in file order
        self.tile.sort(key=_tilesort)

        # FIXME: This is a hack to handle TIFF's JpegTables tag.
        prefix = getattr(self, "tile_prefix", b"")

        # Remove consecutive duplicates that only differ by their offset
        self.tile = [
            list(tiles)[-1]
            for _, tiles in itertools.groupby(
                self.tile, lambda tile: (tile[0], tile[1], tile[3])
            )
        ]
        for i, (decoder_name, extents, offset, args) in enumerate(self.tile):
            seek(offset)
            decoder = Image._getdecoder(
                self.mode, decoder_name, args, self.decoderconfig
            )
            try:
                decoder.setimage(self.im, extents)
                if decoder.pulls_fd:
                    decoder.setfd(self.fp)
                    err_code = decoder.decode(b"")[1]
                else:
                    b = prefix
                    while True:
                        read_bytes = self.decodermaxblock
                        if i + 1 < len(self.tile):
                            next_offset = self.tile[i + 1].offset
                            if next_offset > offset:
                                read_bytes = next_offset - offset
                        try:
                            s = read(read_bytes)
                        except (IndexError, struct.error) as e:
                            # truncated png/gif
                            if LOAD_TRUNCATED_IMAGES:
                                break
                            else:
                                msg = "image file is truncated"
                                raise OSError(msg) from e

                        if not s:  # truncated jpeg
                            if LOAD_TRUNCATED_IMAGES:
                                break
                            else:
                                msg = (
                                    "image file is truncated "
                                    f"({len(b)} bytes not processed)"
                                )
                                raise OSError(msg)

                        b = b + s
                        n, err_code = decoder.decode(b)
                        if n < 0:
                            break
                        b = b[n:]
            finally:
                # Need to cleanup here to prevent leaks
                decoder.cleanup()

    self.tile = []
    self.readonly = readonly

    self.load_end()

    if self._exclusive_fp and self._close_exclusive_fp_after_loading:
        self.fp.close()
    self.fp = None

    if not self.map and not LOAD_TRUNCATED_IMAGES and err_code < 0:
        # still raised if decoder fails to return anything
        raise _get_oserror(err_code, encoder=False)

    return Image.Image.load(self)

def mask_1(self) -> Image.Image:
    mask = Image.new("1", (self.size, self.size))
    px = mask.load()
    assert px is not None
    for y in range(mask.height):
        for x in range(mask.width):
            px[y, x] = (x + y) % 2
    return mask

def gradient_L(self) -> Image.Image:
    gradient = Image.new("L", (self.size, self.size))
    px = gradient.load()
    assert px is not None
    for y in range(gradient.height):
        for x in range(gradient.width):
            px[y, x] = (x + y) % 255
    return gradient

def _get_background(
    im: Image.Image,
    info_background: int | tuple[int, int, int] | tuple[int, int, int, int] | None,
) -> int:
    background = 0
    if info_background:
        if isinstance(info_background, tuple):
            # WebPImagePlugin stores an RGBA value in info["background"]
            # So it must be converted to the same format as GifImagePlugin's
            # info["background"] - a global color table index
            assert im.palette is not None
            try:
                background = im.palette.getcolor(info_background, im)
            except ValueError as e:
                if str(e) not in (
                    # If all 256 colors are in use,
                    # then there is no need for the background color
                    "cannot allocate more than 256 colors",
                    # Ignore non-opaque WebP background
                    "cannot add non-opaque RGBA color to RGB palette",
                ):
                    raise
        else:
            background = info_background
    return background

def forward_model(model, model_name, preprocess_val, image_batch, text_batch):
    y = []
    tokenizer = open_clip.get_tokenizer(model_name)
    with torch.no_grad():
        for x_im, x_txt in zip(image_batch, text_batch):
            x_im = torch.stack([preprocess_val(im) for im in x_im])
            x_txt = tokenizer(x_txt)
        y.append(model(x_im, x_txt))
    if type(y[0]) == dict:
        out = {}
        for key in y[0].keys():
            out[key] = torch.stack([batch_out[key] for batch_out in y])
    else:
        out = []
        for i in range(len(y[0])):
            out.append(torch.stack([batch_out[i] for batch_out in y]))
    return out

class TestWrapper(torch.nn.Module):
    output_dict: torch.jit.Final[bool]
    def __init__(self, model, model_name, output_dict=True) -> None:
        super().__init__()
        self.model = model
        self.output_dict = output_dict
        if type(model) in [open_clip.CLIP, open_clip.CustomTextCLIP]:
            self.model.output_dict = self.output_dict
        config = open_clip.get_model_config(model_name)
        self.head = torch.nn.Linear(config["embed_dim"], 2)

    def forward(self, image, text):
        x = self.model(image, text)
        x = x['image_features'] if self.output_dict else x[0]
        assert x is not None  # remove Optional[], type refinement for torchscript
        out = self.head(x)
        return {"test_output": out}

class FlagValue(object):
    __slots__ = ["value", "names", "multi"]

    def _fixvalue(self, value):
        # type: (Any) -> int
        if not value:
            return 0
        if isinstance(value, str):
            value = value.split('+') if self.multi else list(value)
        if isinstance(value, list):
            y = 0
            for i in value:
                y |= 1 << self.names.index(i)
            value = y
        return int(value)

    def __init__(self, value, names):
        # type: (Union[List[str], int, str], Union[List[str], str]) -> None
        self.multi = isinstance(names, list)
        self.names = names
        self.value = self._fixvalue(value)

    def __hash__(self):
        # type: () -> int
        return hash(self.value)

    def __int__(self):
        # type: () -> int
        return self.value

    def __eq__(self, other):
        # type: (Any) -> bool
        return self.value == self._fixvalue(other)

    def __lt__(self, other):
        # type: (Any) -> bool
        return self.value < self._fixvalue(other)

    def __le__(self, other):
        # type: (Any) -> bool
        return self.value <= self._fixvalue(other)

    def __gt__(self, other):
        # type: (Any) -> bool
        return self.value > self._fixvalue(other)

    def __ge__(self, other):
        # type: (Any) -> bool
        return self.value >= self._fixvalue(other)

    def __ne__(self, other):
        # type: (Any) -> bool
        return self.value != self._fixvalue(other)

    def __and__(self, other):
        # type: (int) -> FlagValue
        return self.__class__(self.value & self._fixvalue(other), self.names)
    __rand__ = __and__

    def __or__(self, other):
        # type: (int) -> FlagValue
        return self.__class__(self.value | self._fixvalue(other), self.names)
    __ror__ = __or__
    __add__ = __or__  # + is an alias for |

    def __sub__(self, other):
        # type: (int) -> FlagValue
        return self.__class__(
            self.value & (2 ** len(self.names) - 1 - self._fixvalue(other)),
            self.names
        )

    def __xor__(self, other):
        # type: (int) -> FlagValue
        return self.__class__(self.value ^ self._fixvalue(other), self.names)

    def __lshift__(self, other):
        # type: (int) -> int
        return self.value << self._fixvalue(other)

    def __rshift__(self, other):
        # type: (int) -> int
        return self.value >> self._fixvalue(other)

    def __nonzero__(self):
        # type: () -> bool
        return bool(self.value)
    __bool__ = __nonzero__

    def flagrepr(self):
        # type: () -> str
        warnings.warn(
            "obj.flagrepr() is obsolete. Use str(obj) instead.",
            DeprecationWarning
        )
        return str(self)

    def __str__(self):
        # type: () -> str
        i = 0
        r = []
        x = int(self)
        while x:
            if x & 1:
                try:
                    name = self.names[i]
                except IndexError:
                    name = "?"
                r.append(name)
            i += 1
            x >>= 1
        return ("+" if self.multi else "").join(r)

    def __iter__(self):
        # type: () -> FlagValueIter
        return FlagValueIter(self)

    def __repr__(self):
        # type: () -> str
        return "<Flag %d (%s)>" % (self, self)

    def __deepcopy__(self, memo):
        # type: (Dict[Any, Any]) -> FlagValue
        return self.__class__(int(self), self.names)

    def __getattr__(self, attr):
        # type: (str) -> Any
        if attr in self.__slots__:
            return super(FlagValue, self).__getattribute__(attr)
        try:
            if self.multi:
                return bool((2 ** self.names.index(attr)) & int(self))
            return all(bool((2 ** self.names.index(flag)) & int(self))
                       for flag in attr)
        except ValueError:
            if '_' in attr:
                try:
                    return self.__getattr__(attr.replace('_', '-'))
                except AttributeError:
                    pass
            return super(FlagValue, self).__getattribute__(attr)

    def __setattr__(self, attr, value):
        # type: (str, Union[List[str], int, str]) -> None
        if attr == "value" and not isinstance(value, int):
            raise ValueError(value)
        if attr in self.__slots__:
            return super(FlagValue, self).__setattr__(attr, value)
        if attr in self.names:
            if value:
                self.value |= (2 ** self.names.index(attr))
            else:
                self.value &= ~(2 ** self.names.index(attr))
        else:
            return super(FlagValue, self).__setattr__(attr, value)

    def copy(self):
        # type: () -> FlagValue
        return self.__class__(self.value, self.names)

def format_traceback(no_tb=False):
    e, v, tb = sys.exc_info()
    # This is needed when testing chaining and cause without traceback.
    # We set `err.__traceback__ = None` in tests and apparently that makes
    # `tb` here `None´ with Python 3.11 but not with others.
    if sys.version_info < (3, 11) and no_tb:
        tb = None
    return "".join(traceback.format_exception(e, v, tb)).rstrip()

def get_model_info(self) -> dict:
    """Method to get Hugging Face model information for experiment reproducibility."""

    def get_model_num_params(model) -> int:
        if hasattr(model, "num_parameters"):
            return model.num_parameters()
        if hasattr(model, "parameters"):
            return sum(p.numel() for p in model.parameters())
        else:
            return -1

    def get_model_dtype(model) -> str:
        if hasattr(model, "dtype"):
            return model.dtype
        else:
            return ""

    def get_model_sha(pretrained: str, revision: str) -> str:
        try:
            model_info = HfApi().model_info(repo_id=pretrained, revision=revision)
            return model_info.sha
        except Exception as e:
            eval_logger.debug(
                f"Failed to get model SHA for {pretrained} at revision {revision}. Error: {e}"
            )
            return ""

    model_info = {
        "model_num_parameters": get_model_num_params(self._model),
        "model_dtype": get_model_dtype(self._model),
        "model_revision": self.revision,
        "model_sha": get_model_sha(self.pretrained, self.revision),
    }
    if self.peft:
        model_info["peft_sha"] = get_model_sha(self.peft, self.revision)
    if self.delta:
        model_info["delta_sha"] = get_model_sha(self.delta, self.revision)
    return model_info

def _build_date_trunc(args: t.List[exp.Expression]) -> exp.Expression:
    a0, a1 = seq_get(args, 0), seq_get(args, 1)

    def _is_unit_like(e: exp.Expression | None) -> bool:
        if not (isinstance(e, exp.Literal) and e.is_string):
            return False
        text = e.this
        return not any(ch.isdigit() for ch in text)

    # Determine which argument is the unit
    unit, this = a0, a1 if _is_unit_like(a0) else a1, a0

    return exp.TimestampTrunc(this=this, unit=unit)

