async def send_webhook_message(
    ip: str,
    port: int,
    payload_str: Optional[str],
    url_path: str = "",
    content_len: int = -1,
    content_type: str = "application/json",
    get_method: Optional[str] = None,
    secret_token: Optional[str] = None,
    unix: Optional[Path] = None,
) -> Response:
    headers = {
        "content-type": content_type,
    }
    if secret_token:
        headers["X-Telegram-Bot-Api-Secret-Token"] = secret_token

    if not payload_str:
        content_len = None
        payload = None
    else:
        payload = bytes(payload_str, encoding=TextEncoding.UTF_8)

    if content_len == -1:
        content_len = len(payload)

    if content_len is not None:
        headers["content-length"] = str(content_len)

    url = f"http://{ip}:{port}/{url_path}"

    transport = AsyncHTTPTransport(uds=unix) if unix else None

    async with AsyncClient(transport=transport) as client:
        return await client.request(
            url=url, method=get_method or "POST", data=payload, headers=headers
        )

def test_annotate_funcs(self):
    test_schema = {
        "tbl": {
            "bin_col": "BINARY",
            "str_col": "STRING",
            "bignum_col": "BIGNUMERIC",
            "date_col": "DATE",
            "timestamp_col": "TIMESTAMP",
            "double_col": "DOUBLE",
            "bigint_col": "BIGINT",
            "bool_col": "BOOLEAN",
            "bytes_col": "BYTES",
            "interval_col": "INTERVAL",
            "array_col": "ARRAY<STRING>",
        }
    }

    for i, (meta, sql, expected) in enumerate(
        load_sql_fixture_pairs("optimizer/annotate_functions.sql"), start=1
    ):
        title = meta.get("title") or f"{i}, {sql}"
        dialect = meta.get("dialect") or ""
        sql = f"SELECT {sql} FROM tbl"

        for dialect in dialect.split(", "):
            result = parse_and_optimize(
                annotate_functions, sql, dialect, schema=test_schema, dialect=dialect
            )

            with self.subTest(title):
                self.assertEqual(
                    result.type.sql(dialect),
                    exp.DataType.build(expected, dialect=dialect).sql(dialect),
                )

class TestTextEmbedding(EmbeddingModelBase):
    """A mock text embedding model for testing."""

    supported_modalities: list[str] = ["text"]
    """This class only supports text input."""

    def __init__(self) -> None:
        """The constructor for the mock text embedding model."""
        super().__init__(model_name="mock-model", dimensions=3)

    async def __call__(
        self,
        text: list[TextBlock | str],
        **kwargs: Any,
    ) -> EmbeddingResponse:
        """Return a fixed embedding for testing."""
        embeddings = []
        for t in text:
            if isinstance(t, dict):
                t = t.get("text")
            if t == "This is an apple":
                embeddings.append([0.1, 0.2, 0.3])
            elif t == "This is a banana":
                embeddings.append([0.9, 0.1, 0.4])
            elif t == "apple":
                embeddings.append([0.15, 0.25, 0.35])

        return EmbeddingResponse(
            embeddings=embeddings,
        )

